-- Fictional clubs, players and claim links for the claim characterization (P-CLAIM read and the refused submits).
-- Applied on top of the Prisma migrations, which already seed the PH / CEB location code. Every link's token is
-- the text in the sha256() call, so the cases refer to links by those words. Foreign key and constraint-trigger
-- checks are off for this load (replica role): rows only exist to give the routes something to read.
-- Hand written; rerun apps/api/testdata/tools/capture-claim.test.mjs after any change.
BEGIN;
SET LOCAL session_replication_role = replica;



-- Players. a..01 is registered and owns a phone and an email; the rest are what the links point at.


-- Every player but a..03 has an RTR ID (a..03 is the "no RTR ID yet" case).
SELECT v.pid::uuid, v.rtr, 'c1000000-0000-4000-8000-000000000001', (SELECT id FROM location_codes WHERE country_code = 'PH' AND city_code = 'CEB'), 'PH', 'CEB', DATE '2026-11-14', v.seq
FROM (VALUES
  ('a0000000-0000-4000-8000-000000000001', 'RTR-PH-CEB-111426-0001', 1),
  ('a0000000-0000-4000-8000-000000000002', 'RTR-PH-CEB-111426-0002', 2),
  ('a0000000-0000-4000-8000-000000000004', 'RTR-PH-CEB-111426-0004', 4),
  ('a0000000-0000-4000-8000-000000000005', 'RTR-PH-CEB-111426-0005', 5),
  ('a0000000-0000-4000-8000-000000000006', 'RTR-PH-CEB-111426-0006', 6),
  ('a0000000-0000-4000-8000-000000000007', 'RTR-PH-CEB-111426-0007', 7),
  ('a0000000-0000-4000-8000-000000000008', 'RTR-PH-CEB-111426-0008', 8),
  ('a0000000-0000-4000-8000-000000000009', 'RTR-PH-CEB-111426-0009', 9),
  ('a0000000-0000-4000-8000-00000000000a', 'RTR-PH-CEB-111426-0010', 10)
) AS v(pid, rtr, seq);


-- Player-keyed links (a `players` row).

-- Club records. e..01 is the plain case; the others are one variation each.


